rows=[
('A',15,[1,0,0,1]),
('A',9,[0,1,1,1]),
('B',6,[1,0,0,0]),
('B',5,[0,1,0,0]),
('C',9,[1,1,1,1]),
('C',5,[0,1,1,0]),
('D',14,[0,0,0,0]),
('D',9,[1,1,1,0])]
tests='TUVW'
cost=[F(8,10),F(12,10),F(7,10),F(14,10)]
loss=[[0,24,11,6],[19,0,19,8],[9,10,0,16],[21,24,20,0]]
def mass(s): return sum(rows[i][1] for i in s)
def stop(s):
    return min((F(sum(rows[i][1]*loss[a]['ABCD'.index(rows[i][0])] for i in s),mass(s)), 'ABCD'[a]) for a in range(4))
def value(s,avail,budget):
    choices=[stop(s)]
    if budget:
        for t in avail:
            v=cost[t]
            for b in [0,1]:
                sub=[i for i in s if rows[i][2][t]==b]
                if sub: v+=F(mass(sub),mass(s))*value(sub,[j for j in avail if j!=t],budget-1)[0]
            choices.append((v,tests[t]))
    return min(choices)
