from fractions import Fraction as F
rows=[('A',15,[1,0,0,1]),('A',9,[0,1,1,1]),('B',6,[1,0,0,0]),('B',5,[0,1,0,0]),('C',9,[1,1,1,1]),('C',5,[0,1,1,0]),('D',14,[0,0,0,0]),('D',9,[1,1,1,0])]
loss=[[0,24,11,6],[19,0,19,8],[9,10,0,16],[21,24,20,0]]
s=[r for r in rows if r[2][2]==0]
def vals(s):
 return {a:F(sum(r[1]*loss[j]['ABCD'.index(r[0])] for r in s),sum(r[1] for r in s)) for j,a in enumerate('ABCD')}
print('posterior',{a:float(F(sum(r[1] for r in s if r[0]==a),sum(r[1] for r in s))) for a in 'ABCD'})
